use vstd::prelude::*;

verus! {
    type Matrix<T> = Vec<Vec<T>>;

    // The broadcast function takes a vector `a` of length either r or c,
    // and a shape vector of length 2 giving (r, c).  It returns an r×c
    // matrix obtained by broadcasting `a` as a column if |a| = r, or as a
    // row if |a| = c.
    fn broadcast(a: Vec<i8>, shape: Vec<u8>) -> (mat: Matrix<i8>)
        requires
            // shape must be exactly two entries
            shape.len() == 2,
            // interpret shape[0], shape[1] as the dimensions r, c
            let r: usize = shape[0] as usize,
            let c: usize = shape[1] as usize,
            // a must have length matching one of those dimensions
            a.len() == r || a.len() == c,
        ensures
            // the result is an r×c matrix
            mat.len() == r,
            forall |i: usize| i < r ==> mat.index(i).len() == c,
            // and the entries agree with a column broadcast if |a|=r,
            // or a row broadcast if |a|=c
            if a.len() == r {
                forall |i: usize, j: usize| (i < r && j < c) ==> mat.index(i).index(j) == a.index(i)
            } else {
                forall |i: usize, j: usize| (i < r && j < c) ==> mat.index(i).index(j) == a.index(j)
            },
    {
        let r = shape[0] as usize;
        let c = shape[1] as usize;

        if a.len() == r {
            // column‐broadcast case
            let mut mat: Vec<Vec<i8>> = Vec::with_capacity(r);
            // build each row i as vec![a[i]; c]
            for i in 0..r
                invariant
                    // we've pushed exactly i rows so far
                    mat.len() == i,
                    // and each of those rows has the property that
                    // every column k in row j holds a[j]
                    forall |j: usize, k: usize| (j < i && k < c) ==> mat.index(j).index(k) == a.index(j),
                decreases r - i,
            {
                mat.push(vec![a[i]; c]);
            }
            mat
        } else if a.len() == c {
            // row‐broadcast case
            let mut mat: Vec<Vec<i8>> = Vec::with_capacity(r);
            // build r copies of the row a.clone()
            for i in 0..r
                invariant
                    // we've pushed exactly i rows so far
                    mat.len() == i,
                    // and each of those rows j agrees with a on every column k
                    forall |j: usize, k: usize| (j < i && k < c) ==> mat.index(j).index(k) == a.index(k),
                decreases r - i,
            {
                mat.push(a.clone());
            }
            mat
        } else {
            // unreachable by our requires
            panic!(
                "Cannot broadcast array of length {} into shape {}×{}",
                a.len(),
                r,
                c
            );
        }
    }
}

